edits.current:
for (const filename of ['Satoshi-Medium.woff2', 'Satoshi-Bold.woff2']) {
    assert.ok(globalStyles.includes(`/fonts/satoshi/${filename}`));
    const font = readFileSync(
      new URL(`../public/fonts/satoshi/${filename}`, import.meta.url),
    );
    assert.equal(font.subarray(0, 4).toString(), 'wOF2');
  }

